-- 439 Strength of Materials (mechanical)
(439,'govt_basic','som-concept','concept',1,'प्रतिबल और विकृति',$j${"note":"परीक्षा में प्रतिबल का सूत्र और मात्रक पूछे जाते हैं।","text":"बल लगने पर पदार्थ में प्रतिबल पैदा होता है। प्रतिबल = बल / क्षेत्रफल। बल हटाने पर पदार्थ वापस अपनी जगह आ जाए तो वह प्रत्यास्थ है।"}$j$::jsonb,'hi'),
(439,'govt_technical','som-concept','concept',1,'प्रतिबल और विकृति — SSC JE / RRB JE',$j${"note":"JE में प्रतिबल का मात्रक N/m² (Pa) या N/mm² (MPa) अक्सर पूछा जाता है।","text":"बल से पदार्थ में प्रतिबल (stress) और विकृति (strain) उत्पन्न होते हैं। मुख्य प्रकार तनन (tension), संपीड़न (compression) और कर्तन (shear) हैं। Hooke के नियम के अनुसार प्रत्यास्थ सीमा के भीतर प्रतिबल, विकृति के समानुपाती होता है।"}$j$::jsonb,'hi'),
(439,'govt_basic','som-formula','formula',2,'प्रतिबल का सूत्र',$j${"formula":"σ = F / A","explanation":"σ = प्रतिबल (N/m²), F = बल (N), A = क्षेत्रफल (m²)"}$j$::jsonb,'hi'),
(439,'govt_technical','som-formula','formula',2,'सामान्य प्रतिबल',$j${"formula":"σ = F / A","explanation":"σ = सामान्य प्रतिबल (Pa), F = बल (N), A = अनुप्रस्थ क्षेत्रफल (m²) · वृत्ताकार छड़ का A = π d² / 4"}$j$::jsonb,'hi'),
(439,'govt_basic','som-example','example',3,'उदाहरण',$j${"answer":"50 N/m²","question":"एक तार पर 200 N बल है और उसका क्षेत्रफल 4 m² है। प्रतिबल कितना है?","solution":"σ = 200 / 4 = 50 N/m²"}$j$::jsonb,'hi'),
(439,'govt_technical','som-example','example',3,'Numerical (JE style)',$j${"answer":"लगभग 63.7 MPa","question":"10 mm व्यास की छड़ पर 5 kN का तनन बल लगता है। प्रतिबल कितना है?","solution":"A = π/4 × (10)² = 78.5 mm² ⇒ σ = 5000 / 78.5 ≈ 63.7 N/mm²"}$j$::jsonb,'hi'),
(439,'govt_basic','som-mcq','mcq',4,'अभ्यास प्रश्न',$j${"questions":[{"q":"प्रतिबल का SI मात्रक क्या है?","answer":0,"options":["N/m²","N","m","kg"],"explanation":"प्रतिबल = बल/क्षेत्रफल, इसलिए मात्रक N/m² (Pa) है।"},{"q":"जिस सीमा तक बल हटाने पर पदार्थ अपनी मूल लंबाई पर लौट आए, वह कौन सी सीमा है?","answer":0,"options":["प्रत्यास्थ सीमा","टूटने की सीमा","तरल सीमा","ताप सीमा"],"explanation":"प्रत्यास्थ सीमा के भीतर पदार्थ बल हटने पर अपनी मूल अवस्था में लौट आता है।"}]}$j$::jsonb,'hi'),
(439,'govt_technical','som-mcq','mcq',4,'JE MCQs',$j${"questions":[{"q":"Hooke का नियम किस सीमा तक लागू होता है?","answer":0,"options":["प्रत्यास्थ सीमा (elastic limit) तक","टूटने तक","केवल तरल में","कभी नहीं"],"explanation":"प्रत्यास्थ सीमा के भीतर ही प्रतिबल, विकृति के समानुपाती होता है।"},{"q":"बार-बार लगने वाले भार से अचानक विफलता को क्या कहते हैं?","answer":0,"options":["थकान (fatigue) विफलता","तापीय विस्तार","चुंबकत्व","परावर्तन"],"explanation":"बार-बार के भार से पदार्थ कम प्रतिबल पर भी थककर टूट सकता है, इसे fatigue कहते हैं।"}]}$j$::jsonb,'hi'),
(439,null,'som-diagram','svg',5,'तनन में छड़',$j${"svg":"<svg viewBox='0 0 300 120' xmlns='http://www.w3.org/2000/svg'><rect x='30' y='40' width='30' height='40' fill='#60a5fa' rx='3'/><rect x='240' y='40' width='30' height='40' fill='#60a5fa' rx='3'/><line x1='60' y1='60' x2='240' y2='60' stroke='#64748b' stroke-width='4'/><line x1='10' y1='60' x2='30' y2='60' stroke='#14b8a6' stroke-width='3'/><polygon points='30,60 22,55 22,65' fill='#14b8a6'/><line x1='290' y1='60' x2='270' y2='60' stroke='#14b8a6' stroke-width='3'/><polygon points='270,60 278,55 278,65' fill='#14b8a6'/><text x='150' y='100' text-anchor='middle' fill='#64748b' font-size='11'>तनन: दोनों ओर खींचना</text></svg>","caption":"तनन में बल छड़ को लंबा करने की कोशिश करता है"}$j$::jsonb,'hi'),
-- 440 Theory of Machines
(440,'govt_basic','tom-concept','concept',1,'घूमती मशीन',$j${"note":"परीक्षा में RPM और कोणीय वेग का संबंध पूछा जाता है।","text":"मशीन का कोई हिस्सा घूमता है तो उसकी गति को RPM (घूर्णन प्रति मिनट) में मापा जाता है। असंतुलित भाग कंपन पैदा करता है।"}$j$::jsonb,'hi'),
(440,'govt_technical','tom-concept','concept',1,'मशीन में गति और बल — SSC JE / RRB JE',$j${"note":"JE में RPM से कोणीय वेग निकालना और संतुलन के प्रकार पूछे जाते हैं।","text":"थ्योरी ऑफ मशीन्स में लिंक (कड़ी) और जोड़ (pair) की गति का अध्ययन होता है। कोणीय वेग ω = 2πN/60 (N = RPM)। गति के साथ जड़त्व बल और संतुलन (balancing) की गणना भी होती है।"}$j$::jsonb,'hi'),
(440,'govt_basic','tom-formula','formula',2,'कोणीय वेग',$j${"formula":"ω = 2πN / 60","explanation":"ω = कोणीय वेग, N = RPM"}$j$::jsonb,'hi'),
(440,'govt_technical','tom-formula','formula',2,'कोणीय वेग',$j${"formula":"ω = 2πN / 60","explanation":"ω = कोणीय वेग (rad/s), N = घूर्णन प्रति मिनट (RPM)"}$j$::jsonb,'hi'),
(440,'govt_basic','tom-example','example',3,'उदाहरण',$j${"answer":"6.28 rad/s","question":"कोई पहिया 60 RPM से घूमता है। उसका कोणीय वेग कितना है? (π = 3.14 लें)","solution":"ω = 2 × 3.14 × 60 / 60 = 6.28 rad/s"}$j$::jsonb,'hi'),
(440,'govt_technical','tom-example','example',3,'Numerical (JE style)',$j${"answer":"31.4 rad/s","question":"एक शाफ्ट 300 RPM से घूम रहा है। उसका कोणीय वेग कितना है? (π = 3.14 लें)","solution":"ω = 2 × 3.14 × 300 / 60 = 31.4 rad/s"}$j$::jsonb,'hi'),
(440,'govt_basic','tom-mcq','mcq',4,'अभ्यास प्रश्न',$j${"questions":[{"q":"गति मापने की इकाई RPM का पूरा रूप क्या है?","answer":0,"options":["घूर्णन प्रति मिनट","रेडियन प्रति सेकंड","मीटर प्रति सेकंड","किलोग्राम प्रति मिनट"],"explanation":"RPM = Revolutions Per Minute, यानी घूर्णन प्रति मिनट।"},{"q":"असंतुलित घूमती मशीन में क्या पैदा होता है?","answer":0,"options":["कंपन","रोशनी","ध्वनि-रहित गति","ठंडक"],"explanation":"असंतुलन से कंपन और शोर पैदा होते हैं।"}]}$j$::jsonb,'hi'),
(440,'govt_technical','tom-mcq','mcq',4,'JE MCQs',$j${"questions":[{"q":"1 RPM = कितने rad/s के बराबर है? (लगभग)","answer":0,"options":["0.105","1.05","10.5","0.0105"],"explanation":"ω = 2π × 1 / 60 ≈ 0.105 rad/s"},{"q":"जब घूमती मशीन में द्रव्यमान का केंद्र घूर्णन अक्ष पर न हो, तो इसे क्या कहते हैं?","answer":0,"options":["असंतुलन (unbalance)","घर्षण","ऊष्मा","प्रकाश"],"explanation":"द्रव्यमान का केंद्र अक्ष से हटा हो तो असंतुलन होता है और कंपन पैदा होते हैं।"}]}$j$::jsonb,'hi'),
(440,null,'tom-diagram','svg',5,'घूमता शाफ्ट',$j${"svg":"<svg viewBox='0 0 300 120' xmlns='http://www.w3.org/2000/svg'><circle cx='150' cy='60' r='40' fill='none' stroke='#64748b' stroke-width='3'/><circle cx='150' cy='60' r='4' fill='#0f172a'/><line x1='150' y1='60' x2='150' y2='22' stroke='#14b8a6' stroke-width='3'/><path d='M 190 60 A 40 40 0 0 1 170 95' fill='none' stroke='#f59e0b' stroke-width='3'/><text x='150' y='115' text-anchor='middle' fill='#64748b' font-size='11'>ω = 2πN / 60</text></svg>","caption":"घूमते भाग की कोणीय गति RPM से निकलती है"}$j$::jsonb,'hi'),
-- 441 Thermodynamics
(441,'govt_basic','thd-concept','concept',1,'ऊष्मागतिकी',$j${"note":"परीक्षा में पहले नियम का सूत्र और ऊष्मा का मात्रक पूछे जाते हैं।","text":"ऊर्जा नष्ट नहीं होती, केवल बदलती है। गैस को दी गई ऊष्मा का कुछ हिस्सा उसकी आंतरिक ऊर्जा बढ़ाता है और बाकी कार्य करने में जाता है।"}$j$::jsonb,'hi'),
(441,'govt_technical','thd-concept','concept',1,'ऊष्मागतिकी — SSC JE / RRB JE',$j${"note":"JE में पहला नियम (Q = ΔU + W) और ऊष्मा-कार्य की इकाई (J) अक्सर पूछे जाते हैं।","text":"ऊष्मागतिकी का पहला नियम: ऊर्जा नष्ट नहीं होती, केवल रूप बदलती है। ΔU = Q − W, जहाँ Q दी गई ऊष्मा है और W किया गया कार्य। दूसरे नियम के अनुसार ऊष्मा अपने-आप ठंडे से गर्म वस्तु की ओर नहीं जाती।"}$j$::jsonb,'hi'),
(441,'govt_basic','thd-formula','formula',2,'पहला नियम',$j${"formula":"Q = ΔU + W","explanation":"Q = ऊष्मा (J), ΔU = आंतरिक ऊर्जा का बदलाव, W = कार्य (J)"}$j$::jsonb,'hi'),
(441,'govt_technical','thd-formula','formula',2,'पहला नियम',$j${"formula":"Q = ΔU + W","explanation":"Q = दी गई ऊष्मा (J), ΔU = आंतरिक ऊर्जा में परिवर्तन (J), W = किया गया कार्य (J)"}$j$::jsonb,'hi'),
(441,'govt_basic','thd-example','example',3,'उदाहरण',$j${"answer":"60 J","question":"गैस को 100 J ऊष्मा दी गई और उसका आंतरिक ऊर्जा बदलाव 40 J है। गैस ने कितना कार्य किया?","solution":"W = Q − ΔU = 100 − 40 = 60 J"}$j$::jsonb,'hi'),
(441,'govt_technical','thd-example','example',3,'Numerical (JE style)',$j${"answer":"300 J","question":"किसी गैस को 500 J ऊष्मा दी गई और उसने 200 J कार्य किया। आंतरिक ऊर्जा में बदलाव कितना है?","solution":"ΔU = Q − W = 500 − 200 = 300 J"}$j$::jsonb,'hi'),
(441,'govt_basic','thd-mcq','mcq',4,'अभ्यास प्रश्न',$j${"questions":[{"q":"ऊर्जा संरक्षण का नियम किस नियम में है?","answer":0,"options":["पहला नियम","दूसरा नियम","तीसरा नियम","कोई नहीं"],"explanation":"ऊष्मागतिकी का पहला नियम ऊर्जा संरक्षण है।"},{"q":"ऊष्मा का मात्रक क्या है?","answer":0,"options":["Joule","Newton","Pascal","Watt"],"explanation":"ऊष्मा का SI मात्रक Joule (J) है।"}]}$j$::jsonb,'hi'),
(441,'govt_technical','thd-mcq','mcq',4,'JE MCQs',$j${"questions":[{"q":"ऊष्मागतिकी का पहला नियम किस सिद्धांत पर आधारित है?","answer":0,"options":["ऊर्जा संरक्षण","गुरुत्वाकर्षण","चुंबकत्व","प्रकाश का परावर्तन"],"explanation":"पहला नियम ऊर्जा संरक्षण का ही रूप है।"},{"q":"ऊष्मा का SI मात्रक क्या है?","answer":0,"options":["Joule","Watt","Pascal","Newton"],"explanation":"ऊष्मा और कार्य दोनों का SI मात्रक Joule (J) है।"}]}$j$::jsonb,'hi'),
(441,null,'thd-diagram','svg',5,'ऊष्मा और कार्य का प्रवाह',$j${"svg":"<svg viewBox='0 0 300 120' xmlns='http://www.w3.org/2000/svg'><rect x='100' y='30' width='100' height='60' fill='#f59e0b' opacity='0.5' rx='6'/><text x='150' y='65' text-anchor='middle' fill='#0f172a' font-size='12'>गैस (U)</text><line x1='40' y1='60' x2='100' y2='60' stroke='#14b8a6' stroke-width='3'/><polygon points='100,60 92,55 92,65' fill='#14b8a6'/><text x='60' y='52' fill='#14b8a6' font-size='11'>Q</text><line x1='200' y1='60' x2='260' y2='60' stroke='#60a5fa' stroke-width='3'/><polygon points='260,60 252,55 252,65' fill='#60a5fa'/><text x='230' y='52' fill='#60a5fa' font-size='11'>W</text></svg>","caption":"गैस में ऊष्मा आती है और वह कार्य करती है"}$j$::jsonb,'hi')
